def make_table(headers, rows, col_widths=None):
    data = [[Paragraph(h, ParagraphStyle('th', fontName='FreeSerif-Bold', fontSize=9, leading=13, textColor=colors.white))] for h in headers]
    for row in rows:
        data.append([Paragraph(str(c), ParagraphStyle('td', fontName='FreeSerif', fontSize=9, leading=13, textColor=TEXT_PRIMARY)) for c in row])

    avail = A4[0] - 2*inch
    if col_widths is None:
        n = len(headers)
        col_widths = [avail/n]*n
    t = Table(data, colWidths=col_widths, repeatRows=1)
    style_cmds = [
        ('BACKGROUND', (0,0), (-1,0), HEADER_FILL),
        ('TEXTCOLOR', (0,0), (-1,0), colors.white),
        ('VALIGN', (0,0), (-1,-1), 'TOP'),
        ('TOPPADDING', (0,0), (-1,-1), 6),
        ('BOTTOMPADDING', (0,0), (-1,-1), 6),
        ('LEFTPADDING', (0,0), (-1,-1), 8),
        ('RIGHTPADDING', (0,0), (-1,-1), 8),
        ('GRID', (0,0), (-1,-1), 0.4, BORDER),
    ]
    for i in range(1, len(data)):
        if i % 2 == 0:
            style_cmds.append(('BACKGROUND', (0,i), (-1,i), TABLE_STRIPE))
    t.setStyle(TableStyle(style_cmds))
    return t

